import{_ as o,o as d,c,a2 as t}from"./chunks/framework.CFuv5BrO.js";const h=JSON.parse('{"title":"运行时操作账本与宿主生命周期","description":"T1/T2 操作合同、单一事件日志、HostKernel 阶段化恢复、Windows AppContainer、ConPTY 与持久后台进程。","frontmatter":{"title":"运行时操作账本与宿主生命周期","description":"T1/T2 操作合同、单一事件日志、HostKernel 阶段化恢复、Windows AppContainer、ConPTY 与持久后台进程。","outline":[2,3]},"headers":[],"relativePath":"architecture/runtime-operations.md","filePath":"architecture/runtime-operations.md","lastUpdated":1795426969000}'),i={name:"architecture/runtime-operations.md"};function a(r,e,n,l,s,p){return d(),c("div",null,[...e[0]||(e[0]=[t('<h1 id="运行时操作账本与宿主生命周期" tabindex="-1">运行时操作账本与宿主生命周期 <a class="header-anchor" href="#运行时操作账本与宿主生命周期" aria-label="Permalink to &quot;运行时操作账本与宿主生命周期&quot;">​</a></h1><h2 id="目的" tabindex="-1">目的 <a class="header-anchor" href="#目的" aria-label="Permalink to &quot;目的&quot;">​</a></h2><p>工具调用不能只靠内存里的 <code>Promise</code> 记录。进程在写文件、发邮件或执行命令的中途崩溃时，下一进程必须知道“这个操作是否已经发生”，否则会重复副作用。</p><p>M1 引入 T1/T2 操作合同：</p><table tabindex="0"><thead><tr><th>阶段</th><th>持久事实</th><th>含义</th></tr></thead><tbody><tr><td><code>prepared</code></td><td>意图、参数摘要、权限摘要、<code>beforeDigest</code></td><td>还没有执行任何副作用</td></tr><tr><td><code>dispatched</code></td><td>T1 已提交</td><td>工具可能已经开始，副作用可能发生</td></tr><tr><td><code>settled</code></td><td>T2 已提交</td><td>结果已知，可以安全继续</td></tr><tr><td><code>unknown</code></td><td>结算失败、超时、中止、外部写无回执</td><td>结果未知，禁止自动重放</td></tr></tbody></table><p><code>operationId = runId + &quot;:&quot; + toolCallId</code>。同一 <code>operationId</code> 的 <code>prepare</code> 幂等；<code>dispatch</code> 第二次会被拒绝；<code>settle</code> 对同一结果幂等，不同结果会被拒绝。</p><h2 id="存储" tabindex="-1">存储 <a class="header-anchor" href="#存储" aria-label="Permalink to &quot;存储&quot;">​</a></h2><ul><li>服务端：SQLite <code>run_operations</code>；与 runtime journal、背景进程注册表一起进入 schema v40。</li><li>standalone / 评测：<code>JsonlOperationLedger</code>，每次状态转换追加一行并 <code>fsync</code>；重启时回放，损坏的尾行忽略。</li><li>runtime 只依赖 <code>OperationLedger</code> 接口，不直接依赖 <code>node:sqlite</code>；server 通过 <code>SqliteOperationLedger</code> 注入。</li></ul><p>关键字段：</p><ul><li><code>args_hash</code>：防止同一 <code>operationId</code> 换参数重放。</li><li><code>before_digest</code>：本地写执行前的目标文件摘要，供恢复时判断写入是否已经落地。</li><li><code>effect</code>：<code>read</code> / <code>local_write</code> / <code>external_write</code> / <code>destructive</code> / <code>unknown</code>。</li><li><code>effect_ref</code> / <code>receipt_json</code>：外部写的回执和外部效果引用。</li></ul><h2 id="runtime-接入点" tabindex="-1">Runtime 接入点 <a class="header-anchor" href="#runtime-接入点" aria-label="Permalink to &quot;Runtime 接入点&quot;">​</a></h2><ol><li>工具审批通过后，先 <code>prepare</code>，再 <code>dispatch</code>，然后才启动工具。</li><li>工具通过 <code>ToolExecutionHandle</code> 执行：超时或父级取消时 <code>AbortController.abort()</code>，等待 5 秒协作退出；仍未退出则返回 <code>TOOL_TIMEOUT</code> / <code>TOOL_ABORTED</code> 和 <code>orphaned</code> 标记。</li><li>工具返回后 <code>settle</code>。正常返回为 <code>settled</code>；抛错、超时、中止为 <code>unknown</code>。</li><li>已经在 <code>dispatched</code> / <code>unknown</code> / <code>settled</code> 的同一操作，下一进程不会再次执行，而是把 <code>operationUnsettled</code> 结果交给模型并提示先核对状态。</li><li><code>external_write</code> 成功但没有 <code>metadata.receipt</code> 时，操作记为 <code>unknown</code>，run 以失败停车，等待人工核对；不会把“没有回执”当成成功继续。</li></ol><h2 id="windows-进程树" tabindex="-1">Windows 进程树 <a class="header-anchor" href="#windows-进程树" aria-label="Permalink to &quot;Windows 进程树&quot;">​</a></h2><p>Windows 下 <code>taskkill /T</code> 在“父进程刚创建子进程”的窗口里可能返回“operation not supported”，留下孤儿。<code>killShellSession</code> 先枚举 <code>Win32_Process</code> 的父子关系，从叶子向根 <code>Stop-Process</code>，再执行 <code>taskkill /T /F</code> 兜底。</p><h2 id="单一持久事实源" tabindex="-1">单一持久事实源 <a class="header-anchor" href="#单一持久事实源" aria-label="Permalink to &quot;单一持久事实源&quot;">​</a></h2><p>服务端不再写 <code>.hearth/journals/&lt;run&gt;/events.jsonl</code>。<code>SqliteRuntimeJournal</code> 把 runtime 的 <code>run.start</code>、<code>message</code>、<code>tool.dispatched</code>、<code>tool.settled</code>、<code>checkpoint</code>、<code>run.end</code> 等事实写入 SQLite <code>events</code>；JSONL journal 只保留给 standalone / 评测模式。</p><ul><li>事件类型：<code>runtime.run.started</code>、<code>runtime.message</code>、<code>runtime.tool.dispatched</code>、<code>runtime.tool.settled</code>、<code>runtime.checkpoint</code>、<code>runtime.run.ended</code>，其余用 <code>runtime.event</code> 保留原始类型。</li><li>checkpoint 文件是物化视图。写入文件前先追加 <code>runtime.checkpoint.snapshot</code> 事件，事件 payload 带完整 <code>AgentCheckpoint</code>；<code>run_checkpoints.event_seq</code> 指向该事件。</li><li>恢复时先校验 checkpoint 文件的 sha256；文件缺失或损坏时回退到 <code>runtime.checkpoint.snapshot</code> 事件，再从 <code>event_seq</code> 之后回放 <code>runtime.message</code> / <code>runtime.tool.settled</code>，补齐检查点后的消息。</li><li>旧版本没有 <code>event_seq</code> 的 checkpoint 仍可按原有 JSONL journal 路径恢复，迁移期不丢历史任务。</li></ul><h2 id="宿主租约与阶段化恢复" tabindex="-1">宿主租约与阶段化恢复 <a class="header-anchor" href="#宿主租约与阶段化恢复" aria-label="Permalink to &quot;宿主租约与阶段化恢复&quot;">​</a></h2><p><code>HostKernel</code> 持有数据目录的唯一宿主租约，并在调度器恢复完成前保持 <code>/api/ready</code> 为 503。启动阶段按 <code>lease → store → operations → runs → tasks → background → ready</code> 推进；<code>recovering</code> 和 <code>draining</code> 期间，创建任务和继续对话的写路由返回 <code>HOST_NOT_READY</code>。</p><ul><li>租约文件为 <code>hearth.host.lock</code>，同时记录 PID 和进程创建时间。PID 被系统复用时，创建时间不匹配会被判为陈旧锁；进程正常退出会删除锁文件。原生 named mutex 辅助程序将在 Windows 沙箱里程碑接入，当前使用等价的文件租约。</li><li><code>HostKernel.stop()</code> 先把状态切到 <code>draining</code>，由调度器停止接收新任务、取消在跑 run、释放任务租约，最后释放宿主租约。</li><li><code>/api/health</code> 返回 <code>host</code> 快照：<code>phase</code>、<code>step</code>、<code>readyAt</code>、<code>error</code> 和租约信息，桌面 supervisor 与诊断页可直接观察卡在哪个阶段。</li></ul><h2 id="windows-原生沙箱" tabindex="-1">Windows 原生沙箱 <a class="header-anchor" href="#windows-原生沙箱" aria-label="Permalink to &quot;Windows 原生沙箱&quot;">​</a></h2><p>Windows 单机执行器不再依赖 Node ACL runner。<code>apps/native/hearth-native.cs</code> 由系统自带 <code>csc.exe</code> 编译成 <code>hearth-native.exe</code>，提供四个子命令：</p><ul><li><code>lease --name</code>：<code>Global\\Hearth.Host.&lt;name&gt;</code> named mutex，stdin 收到 <code>release</code> 或 EOF 后退出。</li><li><code>process-info --pid</code>：返回 PID 与进程创建时间，供宿主租约判断 PID 复用。</li><li><code>sandbox</code>：创建或复用 AppContainer package SID；只给 workspace、私有 temp、显式 <code>--read</code> / <code>--write</code> 根授权；用 <code>PROC_THREAD_ATTRIBUTE_SECURITY_CAPABILITIES</code> 在 AppContainer 中启动子进程；子进程加入 <code>JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE</code> 的 Job Object；父进程 watchdog 每 500ms 检查 <code>--parent-pid</code>，父死即 <code>TerminateJobObject</code>。</li><li><code>pty</code>：与 <code>sandbox</code> 相同的 AppContainer、ACL 和 Job 约束，但通过 <code>CreatePseudoConsole</code> 分配交互式控制台；stdin/stdout 是 ConPTY 原始字节流，<code>--cols</code> / <code>--rows</code> 指定初始尺寸。resize 通过 stdin 注入 <code>\\x1bHEARTH_RESIZE:cols,rows\\n</code> 触发 <code>ResizePseudoConsole</code>。</li></ul><p><code>WindowsNativeSandboxProvider</code> 只构造 argv 契约，不复制 Win32 代码。<code>workspace-write</code> 给 workspace <code>(OI)(CI)M</code>，<code>read-only</code> 给 <code>(OI)(CI)RX</code>；temp 始终可写；额外写根通过 <code>--write</code>，读根通过 <code>--read</code>。网络默认拒绝：AppContainer 不申请 <code>internetClient</code> capability，因此子进程没有网络身份。<code>net-allowlist</code> 还没有无管理员权限的可靠实现：任务声明 <code>networkHosts</code> 时 provider 直接 fail-closed，不会悄悄给一个“没有网络”的沙箱。helper 缺失、AppContainer 创建失败或 ACL 授权失败同样 fail-closed，不会静默退回完全权限。</p><p>沙箱边界是“文件系统 + 进程 + 网络”三层，而不是只限制 shell 命令字符串。junction/symlink 指向工作区外时，目标没有 AppContainer ACE，读写仍会被拒绝。</p><h2 id="conpty-交互式会话" tabindex="-1">ConPTY 交互式会话 <a class="header-anchor" href="#conpty-交互式会话" aria-label="Permalink to &quot;ConPTY 交互式会话&quot;">​</a></h2><p><code>shell</code> 工具增加 <code>pty: true</code> 与 <code>cols</code> / <code>rows</code>。PTY 会话仍由 <code>WindowsNativeSandboxProvider</code> 构造 argv，helper 走 <code>pty</code> 子命令：AppContainer、Job Object、父进程 watchdog 与普通 sandbox 完全相同，只把管道换成 <code>CreatePseudoConsole</code>。</p><ul><li><code>shell_input</code> 向运行中的会话写入按键；PTY 会话默认追加 <code>\\r</code> 作为回车。</li><li><code>shell_resize</code> 发送 <code>\\x1bHEARTH_RESIZE:cols,rows\\n</code>，由 helper 输入线程识别并调用 <code>ResizePseudoConsole</code>；普通 pipe 会话忽略该操作。</li><li>PTY 输出是 ConPTY 原始字节流，含 ANSI 序列；<code>shell_output</code> 仍按文本增量返回。</li><li>ConPTY 子进程使用 <code>STARTF_USESTDHANDLES</code> + <code>INVALID_HANDLE_VALUE</code>，并禁止句柄继承。否则 helper 的输入线程与子进程会抢同一个 stdin，表现为整行命令不执行或随机丢字符。</li><li>PTY 会话不跨宿主重启恢复；重启时由后台任务注册表标记 <code>lost</code>，不会假装进程仍在运行。</li></ul><h2 id="持久后台任务" tabindex="-1">持久后台任务 <a class="header-anchor" href="#持久后台任务" aria-label="Permalink to &quot;持久后台任务&quot;">​</a></h2><p>每个 shell 会话在启动时写入 SQLite <code>background_processes</code>（<code>session_id</code>、<code>pid</code>、<code>start_time</code>、<code>command</code>、<code>output_path</code>、<code>task_id</code>、<code>run_id</code>、<code>status</code>、<code>exit_code</code>）。表由 <code>SqliteBackgroundTaskRegistry</code> 在同一个 <code>HearthStore</code> 连接上创建，保持单 SQLite 写者。</p><ul><li><code>pid</code> 是 helper 进程；<code>start_time</code> 通过 helper 的 <code>process-info</code> 读取真实进程创建时间，不用 Node 的启动时间近似。</li><li>正常退出写 <code>exited</code>，主动停止写 <code>killed</code>。</li><li>宿主启动时 <code>recoverLost()</code> 扫描 <code>running</code> 记录：PID + 创建时间都匹配才认定是同一进程，先杀进程树再标记 <code>lost</code>；创建时间不匹配视为 PID 复用，只标记 <code>lost</code>，不误杀。</li><li>内存 Map 仍是运行中会话的输出来源；<code>shell_output</code> / <code>shell_wait</code> / <code>shell_kill</code> 在 Map 找不到时回退到注册表与日志文件，并向模型明确返回 <code>lost</code>。</li><li>PTY 会话同样写入注册表，但重启后不尝试恢复终端状态，只做 <code>lost</code> 标记和孤儿清理。</li></ul><h2 id="物理清理与终态证据" tabindex="-1">物理清理与终态证据 <a class="header-anchor" href="#物理清理与终态证据" aria-label="Permalink to &quot;物理清理与终态证据&quot;">​</a></h2><p>0.3.4 把“业务结算”和“物理清理”拆成两条账：工具 <code>settle</code> 只代表结果已知，终态 run 还要执行 cleanup，才能真正结束已登记的 shell 进程，并把 <code>confirmed / failed</code> 写回 <code>run_operations</code>。没有 cleanup handler 的资源会明确记 <code>failed</code> 并留下原因，而不是假装清干净。</p><ul><li>每个终态 run 输出 <code>run-evidence.json</code>：task/run/usage、checkpoint 引用、恢复决策、operations/cleanup、artifacts 与 run 链。</li><li>恢复闸门沿父 run 链检查 prepared/dispatched 操作、运行中后台进程和 checkpoint proof；checkpoint proof 增加 <code>toolsDigest</code>，工具集变化在恢复时可见。</li><li>模型响应被截断且携带工具调用时，整批调用丢弃，连续 3 次失败；非法工具入参只产生 <code>tool.rejected</code>，不写操作账本。</li><li>重试不再复制整个 <code>.hearth</code>，只继承已发布产物与 checkpoint 引用的 tool-results；<code>storage:prune</code> 按保留期、活跃 run、未结算操作和 checkpoint 引用回收旧 run 与未引用输出。</li></ul>',34)])])}const _=o(i,[["render",a]]);export{h as __pageData,_ as default};
